layouts.css:
.aha-header{
  container:aha-header / inline-size;
  position:sticky;top:0;z-index:10;
  font-family:var(--aha-font-product);
  color:var(--aha-text-default);
  background:var(--aha-white);
}
.aha-header *{box-sizing:border-box}
.aha-header p{margin:0}
:where(.aha-header) a{color:inherit;text-decoration:none}
.aha-header button{font-family:inherit}
:where(.aha-header) button{margin:0}
.aha-header__nav{
  position:relative;
  padding:0 var(--aha-space-32);
  background:var(--aha-white);
}
.aha-header__bar{
  display:flex;align-items:center;
  max-width:1280px;min-height:var(--aha-space-64);
  margin:0 auto;
}
.aha-header__brand{display:inline-flex;flex:none;border-radius:var(--aha-radius-xs)}
.aha-header__brand:focus-visible,.aha-header__toggle:focus-visible,.aha-header__link:focus-visible,.aha-header__entry:focus-visible,.aha-header__language:focus-visible,.aha-header__language-entry:focus-visible{
  outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);
}
.aha-header__toggle{
  display:none;margin-inline:auto calc(-1 * var(--aha-space-4));
  width:var(--aha-space-40);height:var(--aha-space-48);
  align-items:center;justify-content:center;padding:0;
  border:0;background:transparent;
  color:var(--aha-text-default);cursor:pointer;
}
.aha-header__toggle-close{display:none}
.aha-header[data-menu="open"] .aha-header__toggle-open{display:none}
.aha-header[data-menu="open"] .aha-header__toggle-close{display:inline-flex}
.aha-header__drawer{display:contents}
.aha-header__menu{display:flex;flex:1;align-items:center;justify-content:space-between;margin-inline-start:var(--aha-space-24)}
.aha-header__links{display:flex;align-items:center}
.aha-header__actions{display:flex;align-items:center;gap:var(--aha-space-16)}
.aha-header__buttons{display:flex;gap:var(--aha-space-16)}
.aha-header__item{position:relative}
.aha-header__link{
  display:inline-flex;align-items:center;gap:var(--aha-space-6);
  height:var(--aha-space-48);
  padding:var(--aha-space-12) var(--aha-space-16);
  border:0;background:transparent;
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);line-height:1.5;
  color:var(--aha-text-default);cursor:pointer;
}
.aha-header__chevron{color:var(--aha-icon-strong);transition:transform var(--aha-motion-mid) var(--aha-ease-out)}
.aha-header__item.is-open .aha-header__chevron{transform:rotate(180deg)}
.aha-header__panel{
  position:absolute;top:100%;z-index:2;
  inset-inline-start:calc(-1 * (var(--aha-space-96) + var(--aha-space-32)));
  display:flex;gap:var(--aha-space-16);
  padding:var(--aha-space-20);
  background:var(--aha-bg-elevated);
  border:1px solid var(--aha-border-default);
  border-radius:var(--aha-radius-lg);
  box-shadow:0 12px 16px -4px rgba(0,0,0,.08),0 4px 6px -2px rgba(0,0,0,.03);
  visibility:hidden;opacity:0;pointer-events:none;
  transform:translateY(calc(-1 * var(--aha-space-32)));
  transition:opacity var(--aha-motion-slow) var(--aha-ease-out),visibility 0s linear var(--aha-motion-slow),transform 0s linear var(--aha-motion-slow);
}
.aha-header__item.is-open>.aha-header__panel{
  visibility:visible;opacity:1;pointer-events:auto;transform:none;
  transition:opacity var(--aha-motion-mid) var(--aha-ease-out),transform var(--aha-motion-mid) var(--aha-ease-out),visibility 0s;
}
.aha-header__panel--products{width:988px;inset-inline-start:calc(-1 * (var(--aha-space-96) + var(--aha-space-28)))}
.aha-header__panel--solutions{flex-direction:column;width:642px}
.aha-header__panel--resources{width:402px;inset-inline-start:calc(-1 * (var(--aha-space-96) + var(--aha-space-40)))}
.aha-header__section{display:flex;flex-direction:column;flex:none;width:180px}
.aha-header__section--slides{width:160px}
.aha-header__panel--solutions .aha-header__section{width:auto}
.aha-header__divider{flex:none;width:1px;background:var(--aha-border-default)}
.aha-header__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));width:100%}
.aha-header__panel--resources .aha-header__grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.aha-header__label{
  padding-inline-start:var(--aha-space-8);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-regular);line-height:var(--aha-space-24);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  color:var(--aha-text-tertiary);
}
.aha-header__entry{
  display:flex;align-items:center;gap:var(--aha-space-8);
  padding:var(--aha-space-8);
  border-radius:var(--aha-radius-xs);
  font-size:var(--aha-size-default);font-weight:var(--aha-weight-regular);line-height:1.3;
  color:var(--aha-text-default);
}
.aha-header__entry:hover{background:var(--aha-bg-hover)}
.aha-header__app{
  display:inline-flex;align-items:center;justify-content:center;flex:none;
  width:var(--aha-space-36);height:var(--aha-space-36);
  border:1px solid var(--aha-border-strong);border-radius:var(--aha-radius-xs);
  background:var(--aha-white);color:var(--aha-text-default);
}
.aha-header__app img{width:var(--aha-space-24);height:var(--aha-space-24)}
.aha-header__preview{
  flex:0 1 348px;min-width:0;height:194px;
  margin-inline-start:calc(var(--aha-space-12) - var(--aha-space-16));
  overflow:hidden;
  border-radius:var(--aha-radius-default);
  background:var(--aha-bg-container-secondary);
}
.aha-header__preview-video{display:block;width:100%;height:100%}
.aha-header__language{
  display:inline-flex;align-items:center;gap:var(--aha-space-6);
  height:var(--aha-space-40);
  padding:var(--aha-space-12) var(--aha-space-10);
  border:0;border-radius:var(--aha-radius-default);background:transparent;
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-tertiary);cursor:pointer;
}
.aha-header__language:hover{background:var(--aha-bg-hover)}
.aha-header__languages{
  display:none;
  position:absolute;top:100%;inset-inline-start:0;z-index:2;
  min-width:128px;
  padding:var(--aha-space-4);
  background:var(--aha-bg-elevated);
  border-radius:var(--aha-radius-default);
  box-shadow:0 6px 16px 0 rgba(0,0,0,.08),0 3px 6px -4px rgba(0,0,0,.12),0 9px 28px 8px rgba(0,0,0,.05);
}
.aha-header__item.is-open>.aha-header__languages{display:block}
.aha-header__language-entry{
  display:flex;
  padding:var(--aha-space-8) var(--aha-space-12);
  border-radius:var(--aha-radius-xs);
  font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);line-height:1.5;
  color:var(--aha-gray-80);
}
.aha-header__language-entry:hover{background:var(--aha-bg-accent)}
@keyframes aha-header-drop{from{opacity:0;transform:translateY(calc(-1 * var(--aha-space-32)))}to{opacity:1;transform:none}}
@container aha-header (max-width:991px){
  .aha-header__toggle{display:inline-flex}
  .aha-header__drawer{
    display:block;position:absolute;top:100%;inset-inline:0;z-index:1;
    height:100dvh;overflow:hidden;
    visibility:hidden;transition:visibility 0s linear var(--aha-motion-slow);
  }
  .aha-header[data-menu="open"] .aha-header__drawer{visibility:visible;transition:none}
  .aha-header__menu{
    display:block;height:100%;overflow-y:auto;margin:0;
    padding:var(--aha-space-24) var(--aha-space-16) var(--aha-space-80);
    border-top:1px solid var(--aha-gray-30);
    background:var(--aha-white);
    transform:translateY(-100%);
    transition:transform var(--aha-motion-slow) var(--aha-ease-in-out);
  }
  .aha-header[data-menu="open"] .aha-header__menu{transform:none;transition:transform var(--aha-motion-slow) var(--aha-ease-out)}
  .aha-header__links{flex-direction:column;align-items:stretch;gap:var(--aha-space-8)}
  .aha-header__link{width:100%;justify-content:space-between;height:auto;padding:var(--aha-space-12) 0;font-size:var(--aha-size-default)}
  .aha-header__chevron{color:var(--aha-icon-muted)}
  .aha-header__panel{
    position:static;display:none;flex-direction:column;gap:var(--aha-space-28);
    width:auto;padding:0;border:0;border-radius:0;box-shadow:none;
    visibility:visible;opacity:1;pointer-events:auto;transform:none;transition:none;
  }
  .aha-header__item.is-open>.aha-header__panel{display:flex;animation:aha-header-drop var(--aha-motion-slow) var(--aha-ease-out)}
  .aha-header__section,.aha-header__section--slides{width:auto}
  .aha-header__divider,.aha-header__preview{display:none}
  .aha-header__grid,.aha-header__panel--resources .aha-header__grid{grid-template-columns:minmax(0,1fr)}
  .aha-header__actions{flex-direction:column;align-items:stretch;gap:var(--aha-space-16);margin-top:var(--aha-space-24);padding-bottom:calc(var(--aha-space-96) + var(--aha-space-16))}
  .aha-header__buttons{order:-1}
  .aha-header__buttons aha-button{flex:1}
  .aha-header__item--language{align-self:center}
}
@container aha-header (max-width:767px){
  .aha-header__nav{--aha-web-gutter:var(--aha-space-24);padding:0 var(--aha-web-gutter)}
  .aha-header__menu{padding-inline:var(--aha-web-gutter)}
}
@container aha-header (max-width:479px){
  .aha-header__nav{--aha-web-gutter:var(--aha-space-16);}
}
@media (prefers-reduced-motion:reduce){
  .aha-header *{transition:none!important;animation:none!important}
}
